(()=>{'use strict';
 const states=[['open','در دست اقدام','blue'],['review','منتظر تأیید','yellow'],['done','تمام‌شده','purple']];
 const $=s=>document.querySelector(s);
 const currentTasks=()=>{if(!['mine','all'].includes(scope))return[];const ids=[...document.querySelectorAll('#sharedContent [data-task],#sharedContent [data-shared-card]')].filter(n=>!n.closest('[data-sort-filtered]')).map(n=>n.dataset.task||n.dataset.sharedCard);if(ids.length)return [...new Map(ids.map(id=>[id,tasks.find(t=>t.id===id)])).values()].filter(Boolean);return tasks.filter(t=>(scope==='all'||own(t)||collaborating(t))&&(phase==='all'||t.status===phase)&&SamandisTaskMatches(t,search))};
 function cards(counts){return '<div class="desk-metrics dashboard-filter-metrics">'+states.map(([key,label,color])=>'<button class="desk-metric '+color+'" data-dashboard-phase="'+key+'"><span>'+label+'<b>'+fa(counts[key])+'</b></span></button>').join('')+'</div>'}
 function ensure(){if(!['mine','all'].includes(scope)||$('.desk-metrics'))return;const content=$('#sharedContent');if(!content)return;const title=scope==='mine'?'کارهای من':'همه کارها',sub=scope==='mine'?'کارهایی که به شما سپرده شده یا با همکاری شما پیش می‌رود.':'همهٔ کارهای تیم، در یک نگاه.';content.insertAdjacentHTML('afterbegin','<div class="desk-shared-heading"><small>فضای کاری / '+(scope==='mine'?'شخصی':esc(project?.name||''))+'</small><h1>'+title+'</h1><p>'+sub+'</p></div>'+cards({open:0,review:0,done:0}));}
 function sync(){ensure();const host=$('.desk-metrics');if(!host)return;const rows=currentTasks(),counts={open:0,review:0,done:0};rows.forEach(t=>{if(counts[t.status]!==undefined)counts[t.status]++});for(const [key] of states){const value=host.querySelector('[data-dashboard-phase="'+key+'"] b')||host.querySelector('[data-desk-phase="'+key+'"] b');if(value)value.textContent=fa(counts[key])}host.querySelectorAll('[data-dashboard-phase]').forEach(b=>b.onclick=()=>{phase=b.dataset.dashboardPhase;render()})}
 const oldRender=render;render=function(...args){const result=oldRender(...args);queueMicrotask(sync);return result};const oldTasks=renderTasks;renderTasks=function(...args){const result=oldTasks(...args);queueMicrotask(sync);return result};document.addEventListener('change',e=>{if(e.target.closest('.task-sort-refine'))queueMicrotask(sync)});sync();
})();
